#include "Vgeneration_component_top.h"
#include "generation_metadata.hpp"
#include <iostream>
using namespace generation_event;
int main(){Vgeneration_component_top v;Barrier b;b.delay=4;int checks=0,releases=0;for(int t=0;t<2000;t++){Barrier::Inputs i;i.reset=t==0||t==777;i.arm=b.state==Barrier::IDLE&&t%3!=0;i.arm_generation=b.next_generation;i.arrival=b.state==Barrier::COLLECT&&t%4!=0;i.arrival_generation=b.generation;i.expected_mask=15;i.arrival_mask=(~b.arrived&15)&-(~b.arrived&15);i.release_ready=t%5!=0;auto s=b.signals(i);v.clk=0;v.rst=i.reset;v.arm=i.arm;v.arrival=i.arrival;v.release_ready=i.release_ready;v.ag=i.arm_generation;v.rg=i.arrival_generation;v.em=i.expected_mask;v.am=i.arrival_mask;v.eval();if(!i.reset){auto eq=[&](uint64_t a,uint64_t z){checks++;if(a!=z){std::cerr<<t<<" mismatch "<<a<<" "<<z<<"\n";std::exit(1);}};eq(v.arm_ready,s.arm_ready);eq(v.arrival_ready,s.arrival_ready);eq(v.release_valid,s.release);eq(v.active,s.active);eq(v.generation,s.generation);eq(v.release_mask,s.release_mask);eq(v.arrived_mask,s.arrived_mask);releases+=s.release&&i.release_ready;}v.clk=1;v.eval();b.edge(i);}std::cout<<"GENERATION_METADATA_PASS cycles=2000 checks="<<checks<<" releases="<<releases<<"\n";}
